"""No internal notes in what the site ships.

GitHub Pages serves this repo as it is, so every HTML and CSS comment is public: view-source shows old prices, rival
names, file paths and who decided what. The CEO's QC found "One-time $64.50" in the home page's inline CSS (2026-11-08).

Allowed, because tools find their regions by them:
  <!-- name:begin -->, <!-- name:end -->, <!-- name:begin (written by _tools/x.py) -->
  <!-- Generated by _tools/x.py. Edit that, not this file. -->   (one short line pointing at the generator)
Everything else is an internal note: --write removes it, --check (the pre-push gate) fails on it.

Rationale that used to live in those comments is in git history. Write new rationale in the generator or the commit.

    python3 _tools/shipped_comments.py --check
    python3 _tools/shipped_comments.py --write
    python3 _tools/shipped_comments.py --selftest
"""
from __future__ import annotations

import difflib
import re
import sys
from pathlib import Path

SITE = Path(__file__).resolve().parents[1]

HTML_COMMENT = re.compile(r"<!--(.*?)-->", re.S)
CSS_COMMENT = re.compile(r"/\*.*?\*/", re.S)
RAW = re.compile(r"(<(script|style)\b[^>]*>)(.*?)(</\2>)", re.S | re.I)
ALLOWED = re.compile(r"\s*(?:[a-z0-9-]+:(?:begin|end)(?: \(written by _tools/[a-z0-9_]+\.py\))?"
                     r"|Generated by _tools/[a-z0-9_]+\.py\. Edit (?:that|the generator), not this (?:file|page)\.)\s*")


def shipped() -> list[Path]:
    out = []
    for p in sorted(list(SITE.rglob("*.html")) + list(SITE.rglob("*.css"))):
        rel = p.relative_to(SITE)
        if any(part.startswith(("_", ".")) for part in rel.parts) or "node_modules" in rel.parts:
            continue
        out.append(p)
    return out


def _strip_css(css: str) -> tuple[str, list[str]]:
    found = [m.group(0) for m in CSS_COMMENT.finditer(css)]
    return CSS_COMMENT.sub("", css), found


def clean(text: str, is_css: bool) -> tuple[str, list[str]]:
    """(text without internal notes, the notes removed)."""
    if is_css:
        out, found = _strip_css(text)
        return out, found
    found: list[str] = []
    pieces, pos = [], 0
    for m in RAW.finditer(text):
        before = text[pos:m.start()]
        pieces.append(_strip_html(before, found))
        body = m.group(3)
        if m.group(2).lower() == "style":
            body, css_found = _strip_css(body)
            found += css_found
        pieces.append(m.group(1) + body + m.group(4))
        pos = m.end()
    pieces.append(_strip_html(text[pos:], found))
    return "".join(pieces), found


def _strip_html(chunk: str, found: list[str]) -> str:
    def drop(m: re.Match) -> str:
        if ALLOWED.fullmatch(m.group(1)):
            return m.group(0)
        found.append(m.group(0))
        return ""
    return HTML_COMMENT.sub(drop, chunk)


def run(write: bool) -> int:
    bad = {}
    for p in shipped():
        src = p.read_text(encoding="utf-8")
        out, found = clean_lines(src, p.suffix == ".css")
        if found:
            bad[str(p.relative_to(SITE))] = found
            if write:
                p.write_text(out, encoding="utf-8")
    total = sum(len(v) for v in bad.values())
    if write:
        print(f"shipped comments: removed {total} internal notes from {len(bad)} files")
        return 0
    if bad:
        print(f"FAIL: {total} internal notes in {len(bad)} shipped files (run _tools/shipped_comments.py --write):")
        for rel, found in list(bad.items())[:8]:
            print(f"  {rel}: {found[0][:90]!r}" + (f" (+{len(found) - 1} more)" if len(found) > 1 else ""))
        return 1
    print(f"OK: no internal notes in {len(shipped())} shipped HTML and CSS files")
    return 0


def clean_lines(src: str, is_css: bool) -> tuple[str, list[str]]:
    """clean(), then remove only the lines a removed comment left blank (lines that were blank before stay)."""
    out, found = clean(src, is_css)
    if not found:
        return src, found
    before = src.splitlines(keepends=True)
    after = out.splitlines(keepends=True)
    # A line left holding only whitespace that held text before was a comment line: drop it.
    result = []
    sm = difflib.SequenceMatcher(a=before, b=after, autojunk=False)
    for tag, i1, i2, j1, j2 in sm.get_opcodes():
        if tag == "equal":
            result += after[j1:j2]
        else:
            result += [line for line in after[j1:j2] if line.strip()]
    return "".join(result), found


def selftest() -> int:
    cases = [
        ("<p>a</p><!-- One-time $64.50 -->\n", False, "<p>a</p>\n", 1),
        ("<!-- xsell:begin (written by _tools/thankyou_xsell.py) --><p>x</p><!-- xsell:end -->", False, None, 0),
        ("<!-- de-box:begin --><aside></aside><!-- de-box:end -->", False, None, 0),
        ("<!-- Generated by _tools/landing_pages.py. Edit that, not this file. -->", False, None, 0),
        ("<!-- Generated by _tools/landing_pages.py — a door for /x/, noindex -->", False, "", 1),
        ("<style>a{color:red}/* Linear ships rgb(8,9,10) */</style>", False, "<style>a{color:red}</style>", 1),
        ("<script>var s='<!-- not a comment -->'; /* js */</script>", False, None, 0),
        ("a{b:c}\n/* THE TRUST ROW SAT FLUSH */\nd{e:f}\n", True, "a{b:c}\nd{e:f}\n", 1),
        ("<div>\n  <!-- note\n       two lines -->\n  <p>k</p>\n\n</div>\n", False, "<div>\n  <p>k</p>\n\n</div>\n", 1),
    ]
    for src, is_css, want, n in cases:
        out, found = clean_lines(src, is_css)
        if len(found) != n or (want is not None and out != want) or (want is None and out != src):
            print(f"FAIL: selftest {src[:50]!r} -> {out!r} ({len(found)} found, wanted {n})")
            return 1
    print(f"OK: {len(cases)} shipped-comment cases")
    return 0


if __name__ == "__main__":
    if "--selftest" in sys.argv:
        sys.exit(selftest())
    sys.exit(run("--write" in sys.argv))
